import * as T from './vendor/three.module.js';
import {forestHeight,trailX,riverZ,walkHeight} from './forest-math.js';

export function buildForest(){
 const root=new T.Group(),staticRoot=new T.Group();root.add(staticRoot);const colliders=[];let seed=8026;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296};
 const materials=new Map();const mat=(color,roughness=.9)=>{if(!materials.has(color))materials.set(color,new T.MeshStandardMaterial({color,roughness}));return materials.get(color)};
 const wood=mat('#745c43'),dark=mat('#343e35'),stone=mat('#858d7b'),brass=mat('#bd9b57');
 const mesh=(p,g,m,x=0,y=0,z=0)=>{const o=new T.Mesh(g,m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;p.add(o);return o};
 const cube=new T.BoxGeometry(1,1,1),sphere=new T.IcosahedronGeometry(1,1);
 const box=(p,x,y,z,w,h,d,m)=>{const o=mesh(p,cube,m,x,y,z);o.scale.set(w,h,d);return o};
 const ball=(p,x,y,z,r,m,scale=[1,1,1])=>{const o=mesh(p,sphere,m,x,y,z);o.scale.set(r*scale[0],r*scale[1],r*scale[2]);return o};
 const beam=(p,a,b,r,m)=>{const v=new T.Vector3(...a),delta=new T.Vector3(...b).sub(v),o=mesh(p,new T.CylinderGeometry(r,r*.8,delta.length(),7),m);o.position.copy(v.addScaledVector(delta,.5));o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),delta.normalize());return o};
 const terrainGeo=new T.PlaneGeometry(180,180,180,180);terrainGeo.rotateX(-Math.PI/2);const pos=terrainGeo.attributes.position,colors=new Float32Array(pos.count*3),moss=new T.Color('#4b5c38'),earth=new T.Color('#786444');
 for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i),h=forestHeight(x,z);pos.setY(i,h);const trail=Math.exp(-(((x-trailX(z))/1.3)**4)),c=moss.clone().lerp(earth,trail).multiplyScalar(.78+rand()*.3);colors.set([c.r,c.g,c.b],i*3);}terrainGeo.setAttribute('color',new T.BufferAttribute(colors,3));terrainGeo.computeVertexNormals();mesh(staticRoot,terrainGeo,new T.MeshStandardMaterial({vertexColors:true,roughness:1}));
 // Build a detailed irregular pine once, then instance it across the entire forest.
 function merge(parts){const pts=[],normals=[];for(const part of parts){const g=part.g.index?part.g.toNonIndexed():part.g.clone();g.applyMatrix4(part.matrix);pts.push(...g.attributes.position.array);normals.push(...g.attributes.normal.array);g.dispose();}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(pts,3));g.setAttribute('normal',new T.Float32BufferAttribute(normals,3));return g;}
 const dummy=new T.Object3D();
 function part(g,x,y,z,sx=1,sy=1,sz=1,rx=0,ry=0,rz=0){dummy.position.set(x,y,z);dummy.scale.set(sx,sy,sz);dummy.rotation.set(rx,ry,rz);dummy.updateMatrix();return {g,matrix:dummy.matrix.clone()};}
 const bark=new T.MeshStandardMaterial({color:'#584b3b',roughness:.98});bark.onBeforeCompile=shader=>{shader.vertexShader='varying vec3 localBark;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nlocalBark=position;');shader.fragmentShader='varying vec3 localBark;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>\nfloat grain=sin(localBark.x*95.+localBark.z*82.+sin(localBark.y*8.)*1.2);diffuseColor.rgb*=.83+grain*.17;');};
 const leaf=new T.MeshStandardMaterial({color:'#446244',roughness:.96,emissive:'#213025',emissiveIntensity:.25});leaf.onBeforeCompile=shader=>{shader.vertexShader='varying vec3 localLeaf;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nlocalLeaf=position;');shader.fragmentShader='varying vec3 localLeaf;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>\nfloat needles=sin(localLeaf.x*91.+localLeaf.z*74.)*sin(localLeaf.y*97.);diffuseColor.rgb*=.87+needles*.13;');};
 const treeLocations=[];
 for(let i=0;i<540;i++){let x=rand()*125-62.5,z=rand()*135-56;const near=Math.abs(x)<26&&z<51&&z> -43;if(Math.abs(x-trailX(z))<3.0||Math.abs(z-riverZ(x))<5.5||Math.hypot(x-4,z-41)<5)continue;treeLocations.push({x,z,scale:.62+rand()*.65,angle:rand()*6.28,variant:i%3});if(near)colliders.push({x,z,r:.25});}
 for(let variant=0;variant<3;variant++){
  const barkParts=[],leafParts=[];const trunkGeo=new T.CylinderGeometry(.08,.3,12,9);barkParts.push(part(trunkGeo,0,6,0));
  for(let layer=0;layer<9;layer++){const y=3+layer*.95,reach=2.8-layer*.27;for(let j=0;j<5;j++){const a=j/5*Math.PI*2+layer*.7+variant*.8,l=reach*(.85+rand()*.25),x=Math.cos(a)*l*.5,z=Math.sin(a)*l*.5;const branch=new T.CylinderGeometry(.025,.08,l,5);barkParts.push(part(branch,x,y-.13,z,1,1,1,Math.PI/2,a-Math.PI/2,.16));leafParts.push(part(sphere,x,y-.04,z,l*.68,.29+rand()*.16,.51,.07,a,Math.sin(a)*.12));leafParts.push(part(sphere,Math.cos(a)*l*.87,y-.15,Math.sin(a)*l*.87,.66,.27,.43,.1,a,0));}}
  leafParts.push(part(sphere,0,11.4,0,.38,.75,.38));const bg=merge(barkParts),lg=merge(leafParts),locations=treeLocations.filter(p=>p.variant===variant);for(const [g,m] of [[bg,bark],[lg,leaf]]){const inst=new T.InstancedMesh(g,m,locations.length);locations.forEach((p,i)=>{dummy.position.set(p.x,forestHeight(p.x,p.z),p.z);dummy.rotation.set(0,p.angle,0);dummy.scale.setScalar(p.scale);dummy.updateMatrix();inst.setMatrixAt(i,dummy.matrix);if(m===leaf)inst.setColorAt(i,new T.Color('#a2b088').multiplyScalar(.72+rand()*.28))});inst.castShadow=true;inst.receiveShadow=true;staticRoot.add(inst);}}
 // Tall pale trunks, branching crowns and mottled bark near the trail.
 const birchBark=new T.MeshStandardMaterial({color:'#b9bcb1',roughness:1});birchBark.onBeforeCompile=shader=>{shader.vertexShader='varying vec3 barkPoint;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nbarkPoint=position;');shader.fragmentShader='varying vec3 barkPoint;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>\nfloat scars=step(.78,sin(barkPoint.y*17.+sin(barkPoint.x*29.))*sin(barkPoint.z*23.+barkPoint.x*33.));diffuseColor.rgb=mix(diffuseColor.rgb,vec3(.19,.23,.2),scars*.75);');};
 for(let i=0;i<43;i++){const z=-39+rand()*83,x=trailX(z)+(rand()>.5?1:-1)*(3.5+rand()*5);if(Math.abs(z-riverZ(x))<5.5)continue;const y=forestHeight(x,z),h=10+rand()*7;const g=new T.Group();g.position.set(x,y,z);staticRoot.add(g);mesh(g,new T.CylinderGeometry(.065,.23,h,10),birchBark,0,h/2,0);for(let j=0;j<7;j++){const a=j*2.4;beam(g,[0,h*.6,0],[Math.cos(a)*1.5,h*.88,Math.sin(a)*1.5],.06,birchBark);ball(g,Math.cos(a)*1.6,h*.9+(j%2)*.7,Math.sin(a)*1.6,1.5,mat('#72805a'),[1,.55,1]);}colliders.push({x,z,r:.24});}
 // Ferns, tufted grass and pebbles visible at walking height.
 const grassGeo=new T.BufferGeometry(),grassPts=[];for(let i=0;i<5;i++){const a=i*2.4;grassPts.push(-.035,0,0,.035,0,0,Math.cos(a)*.2,.28+i*.05,Math.sin(a)*.2);}grassGeo.setAttribute('position',new T.Float32BufferAttribute(grassPts,3));grassGeo.computeVertexNormals();const uTime={value:0};const grassMat=new T.MeshStandardMaterial({color:'#798354',side:T.DoubleSide,roughness:1});grassMat.onBeforeCompile=shader=>{shader.uniforms.uTime=uTime;shader.vertexShader='uniform float uTime;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\ntransformed.x+=sin(uTime+instanceMatrix[3].z)*position.y*.14;');};
 const grass=new T.InstancedMesh(grassGeo,grassMat,6500);let count=0;for(let i=0;i<6500;i++){const x=rand()*65-32.5,z=rand()*105-48;if(Math.abs(x-trailX(z))<1.2||Math.abs(z-riverZ(x))<4.2)continue;dummy.position.set(x,forestHeight(x,z),z);dummy.rotation.set(0,rand()*6.28,0);dummy.scale.setScalar(.6+rand()*1.4);dummy.updateMatrix();grass.setMatrixAt(count++,dummy.matrix);}grass.count=count;root.add(grass);
 for(let i=0;i<80;i++){const z=-37+rand()*86,x=trailX(z)+(rand()>.5?1:-1)*(1.8+rand()*3.5);if(Math.abs(z-riverZ(x))<5.5)continue;const y=forestHeight(x,z);const g=new T.Group();g.position.set(x,y,z);g.rotation.y=rand()*6.28;staticRoot.add(g);for(let j=0;j<6;j++){const a=j*Math.PI/3;beam(g,[0,0,0],[Math.cos(a)*.65,.4,Math.sin(a)*.65],.012,mat('#647846'));for(let k=1;k<6;k++){const f=k/6;for(const s of [-1,1]){const o=box(g,Math.cos(a)*.65*f+s*Math.sin(a)*.09,.4*f,Math.sin(a)*.65*f-s*Math.cos(a)*.09,.19,.025,.055,mat('#647846'));o.rotation.y=-a;}}}}
 for(let i=0;i<155;i++){const x=rand()*60-30,z=rand()*100-43;if(Math.abs(x-trailX(z))<1.1||Math.abs(z-riverZ(x))<4.3)continue;const r=.1+rand()*.6;ball(staticRoot,x,forestHeight(x,z)+r*.25,z,r,stone,[1.6,.75,1]);if(r>.4&&Math.abs(x)<24)colliders.push({x,z,r:r*.9});}
 // River, softly animated currents and a board-by-board bridge.
 const waterPts=[],indices=[];for(let i=0;i<=160;i++){const x=-90+i*180/160,z=riverZ(x);waterPts.push(x,-.36,z-3.5,x,-.36,z+3.5);if(i<160){const k=i*2;indices.push(k,k+1,k+2,k+1,k+3,k+2)}}const waterGeo=new T.BufferGeometry();waterGeo.setAttribute('position',new T.Float32BufferAttribute(waterPts,3));waterGeo.setIndex(indices);waterGeo.computeVertexNormals();const waterMat=new T.MeshPhysicalMaterial({color:'#426e71',roughness:.2,metalness:.15,clearcoat:1,side:T.DoubleSide});const river=mesh(root,waterGeo,waterMat);river.castShadow=false;
 const currents=new T.Group();root.add(currents);for(let i=0;i<65;i++){const x=rand()*140-70,z=riverZ(x)+(rand()-.5)*6;const l=new T.Line(new T.BufferGeometry().setFromPoints([new T.Vector3(-.4,0,0),new T.Vector3(.4,0,0)]),new T.LineBasicMaterial({color:'#c6c8a2',transparent:true,opacity:.25}));l.position.set(x,-.335,z);currents.add(l);}
 for(let i=0;i<54;i++){const z=6.8+i*.2,x=trailX(z);box(staticRoot,x,.71,z,2.7,.08,.18,wood);if(i%8===0)for(const side of [-1,1]){beam(staticRoot,[x+side*1.25,-2,z],[x+side*1.25,1.64,z],.075,wood);ball(staticRoot,x+side*1.25,1.68,z,.09,wood)}}
 for(const side of [-1,1])for(let i=0;i<53;i++){const z=6.8+i*.2;beam(staticRoot,[trailX(z)+side*1.25,1.34,z],[trailX(z+.2)+side*1.25,1.34,z+.2],.035,wood);}
 // A small forest shelter and fire lookout frame the end of the walk.
 const lx=trailX(44),lz=44,ly=forestHeight(lx,lz);for(const x of [-1.6,1.6])for(const z of [-1.6,1.6]){beam(staticRoot,[lx+x,ly,lz+z],[lx+x*.7,ly+7,lz+z*.7],.14,wood);beam(staticRoot,[lx+x,ly+.8,lz+z],[lx-x*.7,ly+6.8,lz+z*.7],.07,wood)}box(staticRoot,lx,ly+7,lz,3.6,.18,3.6,wood);const windowGlass=new T.MeshStandardMaterial({color:'#adc2b7',transparent:true,opacity:.12,roughness:.2,metalness:.1,depthWrite:false});for(const side of [-1,1]){box(staticRoot,lx+side*1.35,ly+7.5,lz,.08,.8,2.7,wood);box(staticRoot,lx,ly+7.5,lz+side*1.35,2.7,.8,.08,wood);for(const other of [-1,1])box(staticRoot,lx+side*1.35,ly+8.2,lz+other*1.35,.1,2.4,.1,wood);}for(const side of [-1,1]){box(staticRoot,lx+side*1.37,ly+8.4,lz,.025,1.04,2.2,windowGlass);box(staticRoot,lx,ly+8.4,lz+side*1.37,2.2,1.04,.025,windowGlass);}mesh(staticRoot,new T.ConeGeometry(2.3,1.2,4),mat('#4c4c40'),lx,ly+9.8,lz).rotation.y=Math.PI/4;
 // Timber steps lead from the path to the raised lookout platform.
 for(let i=0;i<26;i++){const z=37+i*7/25,x=trailX(z),y=walkHeight(x,z);box(staticRoot,x,y-.04,z,2.3,.13,.28,wood);if(i%4===0)for(const side of [-1,1])beam(staticRoot,[x+side*1.1,forestHeight(x,z),z],[x+side*1.1,y+.9,z],.06,wood);if(i>0)for(const side of [-1,1])beam(staticRoot,[trailX(z-.28)+side*1.1,walkHeight(trailX(z-.28),z-.28)+.9,z-.28],[x+side*1.1,y+.9,z],.033,wood);}
 // Resting bench and sign at the overlook.
 const bx=trailX(39)+2.5,bz=39,by=forestHeight(bx,bz);box(staticRoot,bx,by+.48,bz,2.2,.12,.5,wood);for(const s of [-1,1]){box(staticRoot,bx+s*.85,by+.2,bz,.12,.5,.4,wood);box(staticRoot,bx,by+.9,bz+.22,2.2,.13,.065,wood);}
 const signx=trailX(-26)+1.65,signy=forestHeight(signx,-26);beam(staticRoot,[signx,signy,-26],[signx,signy+1.5,-26],.08,wood);box(staticRoot,signx,signy+1.4,-26,1.3,.53,.07,wood);
 // An amber lamp hanging from the bridge rail.
 const lantern=new T.Group();root.add(lantern);lantern.position.set(trailX(9)+1.1,1.5,9);box(lantern,0,0,0,.18,.25,.18,dark);const lampGlass=new T.MeshStandardMaterial({color:'#f2c478',emissive:'#eeaa54',emissiveIntensity:1.7,roughness:.3});box(lantern,0,0,-.098,.13,.17,.014,lampGlass);const lampLight=new T.PointLight('#ffad55',3,4);lampLight.position.copy(lantern.position);root.add(lampLight);
 // Sun shafts cross the trail as translucent atmospheric planes.
 const shafts=new T.Group();root.add(shafts);for(let i=0;i<9;i++){const g=new T.PlaneGeometry(1.2+rand()*1.8,25);const m=new T.MeshBasicMaterial({color:'#f6d89a',transparent:true,opacity:.028,depthWrite:false,side:T.DoubleSide,blending:T.AdditiveBlending});const s=mesh(shafts,g,m,-7+rand()*17,9,-35+i*7);s.rotation.z=-.5;s.rotation.y=.45;s.castShadow=false;}
 // Floating dust and blue-hour fireflies use lightweight points.
 const dustGeo=new T.BufferGeometry(),dustArray=new Float32Array(280*3);for(let i=0;i<280;i++)dustArray.set([rand()*42-21,1+rand()*6,rand()*85-36],i*3);dustGeo.setAttribute('position',new T.BufferAttribute(dustArray,3));const dust=new T.Points(dustGeo,new T.PointsMaterial({color:'#ebd49c',size:.055,transparent:true,opacity:.55,depthWrite:false}));root.add(dust);
 // Batch the fine scenery and branch details.
 staticRoot.updateMatrixWorld(true);const batches=new Map();staticRoot.traverse(o=>{if(!o.isMesh||o.isInstancedMesh)return;const key=o.material.uuid;if(!batches.has(key))batches.set(key,[]);batches.get(key).push(o)});for(const objects of batches.values()){if(objects.length<2||objects[0].material.vertexColors)continue;const geometry=merge(objects.map(o=>({g:o.geometry,matrix:o.matrixWorld})));objects.forEach(o=>o.removeFromParent());const batch=new T.Mesh(geometry,objects[0].material);batch.castShadow=true;batch.receiveShadow=true;staticRoot.add(batch);}
 function update(t,mode){uTime.value=t;currents.position.x=Math.sin(t*.18)*.5;dust.rotation.y=Math.sin(t*.05)*.005;dust.material.color.set(mode==='blue'?'#becf8e':'#ebd49c');dust.material.opacity=mode==='blue'?.8:.4;shafts.visible=mode!=='blue';}
 return {root,colliders,update,shafts,lampLight,treeCount:treeLocations.length};
}
